<div class="change-password-panel">
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center"
             style="cursor:pointer" @onclick="() => _expanded = !_expanded">
            <span class="fw-semibold">🔑 Change Password</span>
            <span>@(_expanded ? "▲" : "▼")</span>
        </div>
        @if (_expanded)
        {
            <div class="card-body">
                @if (!string.IsNullOrEmpty(_message))
                {
                    <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show">
                        @_message
                        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                    </div>
                }

                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="_currentPassword" />
                </div>

                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control @(_newPasswordError != null ? "is-invalid" : "")"
                           @bind="_newPassword" />
                    @if (_newPasswordError != null)
                    {
                        <div class="invalid-feedback">@_newPasswordError</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control @(_confirmError != null ? "is-invalid" : "")"
                           @bind="_confirmPassword" />
                    @if (_confirmError != null)
                    {
                        <div class="invalid-feedback">@_confirmError</div>
                    }
                </div>

                <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Update Password
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _newPasswordError;
    private string? _confirmError;
    private string? _message;
    private bool _isError;
    private bool _saving;

    private async Task UpdatePasswordAsync()
    {
        _newPasswordError = null;
        _confirmError = null;
        _message = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _message = "Current password is required.";
            _isError = true;
            return;
        }

        if (_newPassword.Length < 6)
        {
            _newPasswordError = "New password must be at least 6 characters.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _confirmError = "Passwords do not match.";
            return;
        }

        _saving = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _message = "Password updated successfully!";
            _isError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _message = $"Failed to change password: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

