@namespace sv_39886a58ca3e4d5ba8fa0cd57a249c2d.Components.Settings
@using sv_39886a58ca3e4d5ba8fa0cd57a249c2d.Models
@using sv_39886a58ca3e4d5ba8fa0cd57a249c2d.Services
@inject ISettingsService SettingsService

<div class="security-section">
    @if (_loading)
    {
        <div class="text-center py-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="mb-4">Security Settings</h4>

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

        <div class="card my-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <small class="text-muted">Add an extra layer of security to your account</small>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@_twoFactorEnabled"
                               @onchange="e => _twoFactorEnabled = (bool)(e.Value ?? false)" />
                    </div>
                </div>
            </div>
        </div>

        @if (_settings?.LastPasswordChange is not null)
        {
            <p class="text-muted small mb-4">
                Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        <ActiveSessionsTable Sessions="@_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnRevokeRequested="RequestRevoke" />

        <RevokeSessionDialog Visible="@(_sessionToRevoke is not null)"
                             DeviceName="@(_sessionToRevoke?.Device ?? "")"
                             OnConfirm="ConfirmRevokeAsync"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = new();
    private bool _twoFactorEnabled;
