+        {
+            <p class="text-muted small mb-4">
+                Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
+            </p>
+        }
+
+        <ActiveSessionsTable Sessions="@_sessions"
+                             CurrentSessionId="@_currentSessionId"
+                             OnRevokeRequested="RequestRevoke" />
+
+        <RevokeSessionDialog Visible="@(_sessionToRevoke is not null)"
+                             DeviceName="@(_sessionToRevoke?.Device ?? "")"
+                             OnConfirm="ConfirmRevokeAsync"
+                             OnCancel="CancelRevoke" />
+    }
+</div>
+
+@code {
+    private SecuritySettings? _settings;
+    private List<ActiveSession> _sessions = new();
+    private bool _twoFactorEnabled;
+    private string? _currentSessionId;
+    private ActiveSession? _sessionToRevoke;
+    private bool _loading = true;
+    private string? _statusMessage;
+    private bool _isError;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAsync();
+    }
+
+    private async Task LoadAsync()
+    {
+        _loading = true;
+        try
+        {
+            _settings = await SettingsService.GetSecuritySettingsAsync();
+            _twoFactorEnabled = _settings.TwoFactorEnabled;
+            _sessions = _settings.Sessions.ToList();
+            // Treat the first session as "current" for demo purposes
+            _currentSessionId = _sessions.FirstOrDefault()?.Id;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task HandleChangePasswordAsync((string Current, string New) args)
+    {
+        await SettingsService.ChangePasswordAsync(args.Current, args.New);
+    }
+
+    private void RequestRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+    }
+
+    private void CancelRevoke()
+    {
+        _sessionToRevoke = null;
+    }
+
+    private async Task ConfirmRevokeAsync()
+    {
+        if (_sessionToRevoke is null) return;
+
+        try
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
+            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
+            _statusMessage = $"Session on \"{_sessionToRevoke.Device}\" has been revoked.";
+            _isError = false;
+        }
+        catch (Exception ex)
+        {
+            _statusMessage = $"Failed to revoke session: {ex.Message}";
+            _isError = true;
+        }
+        finally
+        {
+            _sessionToRevoke = null;
+        }
+    }
+}
