toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer

@using sv_39886a58ca3e4d5ba8fa0cd57a249c2d.Components.Settings

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-layout">
        <aside class="settings-nav">
            <SettingsSidebar ActiveSection="@_activeSection"
                            OnSectionChanged="section => _activeSection = section" />
        </aside>
        <main class="settings-content">
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        </main>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1.5rem;
}

.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-nav {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

/* Sidebar styles */
.settings-sidebar .nav-pills .nav-link {
    color: var(--bs-body-color);
    border-radius: 0.5rem;
    padding: 0.6rem 1rem;
    margin-bottom: 0.25rem;
    transition: background-color 0.15s ease;
}

.settings-sidebar .nav-pills .nav-link:hover {
    background-color: rgba(var(--bs-primary-rgb), 0.08);
}

.settings-sidebar .nav-pills .nav-link.active {
    background-color: var(--bs-primary);
    color: #fff;
}

/* Preview area transition */
.preview-area {
    transition: all 0.3s ease;
}

/* Responsive: stack on small screens */
@@media (max-width: 768px) {
    .settings-layout {
        flex-direction: column;
        gap: 1rem;
    }

    .settings-nav {
        flex: none;
    }

    .settings-sidebar .nav-pills {
        flex-direction: row !important;
        overflow-x: auto;
    }

    .settings-sidebar .nav-pills .nav-link {
        white-space: nowrap;
    }
}

